import { post } from '../base'

export async function getS3PresignedUrl(url: string) {
  const s3UrlParse = url.replace('s3://', '').split('/')
  if (s3UrlParse.length < 2) {
    return null
  }
  // convert: S3://sekai-stage-data/aiu-character/6205/b3fce712-06a8-4e74-9faf-e17b550db65a.png
  // to aiu-character/6205/b3fce712-06a8-4e74-9faf-e17b550db65a.png
  const fileName = s3UrlParse.slice(3).join('/')
  return post<{
    presignedUrl: string
  }>(
    '/s3/generatePresignedUrl',
    {
      fileName,
      method: 'get_object',
    },
  )
}
