<script setup lang="ts">
import { onUpdated, ref, watch } from 'vue'
import { getS3PresignedUrl } from '@/services/utils/s3'

interface Props {
  src: string
}

const props = defineProps<Props>()
const url = ref('')

onUpdated(() => {
  presignUrl()
})

watch(
  () => props.src,
  () => {
    presignUrl()
  },
  {
    immediate: true,
  },
)

async function presignUrl() {
  // if the src doesn't start with s3, then we use the url directly
  if (props.src.toLowerCase().startsWith('s3')) {
    const res = await getS3PresignedUrl(props.src || '')
    url.value = res?.presignedUrl || ''
  }
  else {
    url.value = props.src
  }
}
</script>

<template>
  <img
    v-if="url !== ''"
    v-bind="$attrs"
    :src="url"
  >
</template>
